{
  "references": [
    {
      "id": "R1",
      "summary_ko": "구름이 그녀의 머리 뒤로 사라짐"
    },
    {
      "id": "R2",
      "summary_ko": "뱀들이 구름에서 거꾸로 형성되며 춤추지 않고 꼬리가 아래로 향함"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "수직의 구름 줄기가 내려오며 코브라 머리와 똬리를 튼 뱀의 몸체로 변형됨"
    },
    {
      "id": "C2",
      "summary_ko": "플루트의 각도와 위치가 입과 손에 대해 급격히 변하고 손가락들이 부자연스럽게 융합되고 표류함"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "머리 뒤로 구름이 사라지는 현상과 구름이 뱀으로 변형되는 현상은 서로 다른 대상을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "구름의 소멸과 플루트 및 손가락의 변형은 전혀 다른 대상 및 결함입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "구름에서 뱀이 형성되는 과정을 다루고 있다는 점은 유사하나, 거꾸로 형성되거나 춤추지 않는 결함 내용과 단순 하강 및 변형 묘사 간에 동일한 결함을 지칭하는지 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "구름에서 뱀이 형성되는 결함과 플루트 및 손의 부자연스러운 움직임은 대상과 현상이 완전히 다릅니다."
    }
  ]
}
